param([ValidateSet('List','Seal','Stage')][string]$Mode='List',[switch]$CpuDebugExitObserved0,[switch]$IncludeValidationStatus,[switch]$StageAuthorized,[string]$ReviewedManifestSha256='')
# Read/hash aggregation and explicit selective staging only; no build/program/commit/push.
$ErrorActionPreference='Stop';$t=Split-Path -Parent $PSScriptRoot;$repo=(Get-Item -LiteralPath $t).Parent.Parent.Parent.Parent.FullName
$base='c91ee27f2d89639db202333e6fc2331f57daa640';$logs=Join-Path $t 'logs';$out=Join-Path $t 'outputs';$tag='upl_gpu_feedback_'
$manifest=Join-Path $logs ($tag+'publish_r2.json');$aggregate=Join-Path $logs ($tag+'stage_r2.check.json')
$baseline=Join-Path $logs ($tag+'r1.baseline.json');$context=Join-Path $t ('notes\'+$tag+'review_r2.json');$cpu=Join-Path $logs ($tag+'CPU_Debug_default_r2.build.log')
$five=@('JSphGpu.h','JSphGpu.cpp','JSphGpuSingle.cpp','JSphGpu_ker.h','JSphGpu_ker.cu')
function ResolveArtifactPath([string]$p){if([IO.Path]::IsPathRooted($p)){$p}else{Join-Path $repo $p}}
function ReadJson([string]$p){Get-Content -Raw -LiteralPath (ResolveArtifactPath $p)|ConvertFrom-Json}
function Entry([string]$p){$f=Get-Item -LiteralPath $p;if(!$f.FullName.StartsWith($repo+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Escaped whitelist'};[ordered]@{path=$f.FullName.Substring($repo.Length+1).Replace('\','/');bytes=$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function VerifyTree($x){if($null -eq $x){return};if($x -is [array]){foreach($v in $x){VerifyTree $v};return};if($x -is [pscustomobject]){if($x.PSObject.Properties['path'] -and $x.PSObject.Properties['sha256'] -and $x.PSObject.Properties['bytes']){$p=ResolveArtifactPath $x.path;$f=Get-Item -LiteralPath $p;if($f.Length -ne $x.bytes -or (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash -ine $x.sha256){throw "Changed binding: $p"};return};foreach($v in $x.PSObject.Properties){VerifyTree $v.Value}}}
function WriteFresh([string]$p,$x){if(Test-Path -LiteralPath $p){throw 'Retained publication protected'};[IO.File]::WriteAllText($p,($x|ConvertTo-Json -Depth 22)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function CheckCall($e,[bool]$mem=$false){VerifyTree $e;$c=ReadJson $e.path;VerifyTree $c;if(!$c.owned_call_exited -or $c.exit_code -ne 0){throw 'Owned exit not0'};if($mem){$s=[IO.File]::ReadAllText((ResolveArtifactPath $c.log.path));if(!$c.memcheck_executed -or !$c.memcheck_zero_errors_and_leaks -or $s -notmatch 'ERROR SUMMARY:\s*0 errors' -or $s -notmatch 'LEAK SUMMARY:\s*0 bytes leaked in 0 allocations'){throw 'Actual memcheck0/0 missing'}}}
function CheckHelper($e){VerifyTree $e;$h=ReadJson $e.path;VerifyTree $h;if($h.status -ne 'actual_authoritative_GPU_objects_helper_linked_not_run' -or !$h.only_chosen_helper_author_files_frozen -or $h.source_build.sha256 -ine $gpuIds[$h.configuration]){throw 'Wrong r2 helper/source'};CheckCall $h.compile_call;CheckCall $h.link_call}
$checks=@(foreach($w in 'Smoke','Extended'){Join-Path $logs ($tag+$w+'_r2.review.check.json')};foreach($c in 'Debug','Release'){foreach($f in 'State','Theta','Feedback'){Join-Path $logs ($tag+$f+'_'+$c+'_r2.check.json')};Join-Path $logs ($tag+'Feedback_'+$c+'_r2_integrated.check.json')})
function Paths {
  $p=@($five|ForEach-Object {Join-Path $repo ('src\source\'+$_)})+@($PSCommandPath,$context)
  foreach($s in @('support\upl_gpu_feedback_build_r1.ps1','support\upl_gpu_feedback_runs_r1.ps1','support\upl_gpu_feedback_r2.ps1','support\upl_gpu_feedback_runs_r2.ps1','support\upl_gpu_feedback_r1.cpp','notes\upl_gpu_feedback_plan_r1.json','notes\upl_gpu_feedback_r1.json','notes\upl_gpu_feedback_r2.json','notes\upl_gpu_feedback_fac_r2.json')){$p+=Join-Path $t $s}
  $p+=Get-ChildItem -LiteralPath $logs -File|Where-Object {$_.Name -like 'upl_gpu_feedback*' -and $_.Extension -eq '.json' -and $_.Name -notmatch '_compare_|_poro_|publish_r1|stage_r1' -and $_.FullName -ne $manifest}|ForEach-Object {$_.FullName}
  $p+=Get-ChildItem -LiteralPath $logs -File|Where-Object {$_.Name -like 'upl_gpu_feedback*' -and $_.Extension -eq '.log' -and ($_.Name -match '_project\.log$|_compile\.log$|_link\.log$|_component\.log$|^upl_gpu_feedback_Smoke_r2_(newoff|observer)\.log$' -or $_.FullName -eq $cpu)}|ForEach-Object {$_.FullName}
  foreach($f in $five){$p+=Join-Path $out ($tag+'Debug_r1\'+$f)}
  foreach($w in 'Smoke','Extended'){foreach($k in 'newoff','observer'){$d=Join-Path $out ($tag+$w+'_r2_'+$k);foreach($f in 'Run.out','Run.csv'){$p+=Join-Path $d $f};if($k -eq 'observer'){foreach($f in 'observer_final.csv','observer_complete.json'){$p+=Join-Path $d $f}}};$d=Join-Path $out ($tag+$w+'_r2_review');if(Test-Path -LiteralPath $d){$p+=Get-ChildItem -LiteralPath $d -File|Where-Object {$_.Extension -in '.csv','.json'}|ForEach-Object {$_.FullName}}}
  foreach($c in 'Debug','Release'){foreach($s in 'State','Theta','Feedback','FeedbackIntegrated'){$d=if($s -eq 'FeedbackIntegrated'){$tag+'Feedback_'+$c+'_r2_integrated_data'}else{$tag+$s+'_'+$c+'_r2_data'};$d=Join-Path $out $d;if(Test-Path -LiteralPath $d){$p+=Get-ChildItem -LiteralPath $d -File|Where-Object {$_.Extension -in '.csv','.json' -or $_.Name -eq 'Run.out'}|ForEach-Object {$_.FullName}}}}
  $d=Join-Path $out ($tag+'Feedback_Debug_r1_integrated_data');$p+=Get-ChildItem -LiteralPath $d -File|Where-Object {$_.Extension -eq '.csv'}|ForEach-Object {$_.FullName}
  if($IncludeValidationStatus){$p+=Join-Path $repo 'examples\Hydromechanic coupling\validation\upl_current_status.json'};@($p|Sort-Object -Unique)
}
if($Mode -eq 'Stage'){
  if(!$StageAuthorized -or $ReviewedManifestSha256 -notmatch '^[0-9a-fA-F]{64}$' -or (Get-FileHash -LiteralPath $manifest -Algorithm SHA256).Hash -ine $ReviewedManifestSha256){throw 'Reviewed SHA/StageAuthorized required'}
  $m=ReadJson $manifest;VerifyTree $m.files;VerifyTree $m.aggregate;$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$head=& git -C $repo rev-parse HEAD;$code=$LASTEXITCODE;$index=@(& git -C $repo -c core.quotepath=false diff --cached --name-only);$ic=$LASTEXITCODE;$ErrorActionPreference=$old
  if($code -or $ic -or $head -ne $base -or $m.base -ne $base -or !$m.ready_for_root_review){throw 'Changed base/index'};$p=@($m.files.path)+@($manifest.Substring($repo.Length+1).Replace('\','/'));foreach($f in $index){if($f -and $f -notin $p){throw 'Unrelated staged changes preserved'}}
  for($i=0;$i -lt $p.Count;$i+=20){$j=[Math]::Min($i+19,$p.Count-1);$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$msg=& git -C $repo --literal-pathspecs add -f -- @($p[$i..$j]) 2>&1;$code=$LASTEXITCODE;$ErrorActionPreference=$old;$msg|Out-Host;if($code){throw 'Preserve partial index'}};exit 0
}
$p=Paths;$missing=@(($p+$checks+@($baseline,$cpu))|Sort-Object -Unique|Where-Object {!(Test-Path -LiteralPath $_)})
if($Mode -eq 'List'){$files=@($p|Where-Object {Test-Path -LiteralPath $_}|ForEach-Object {Entry $_});[pscustomobject]@{count=$files.Count;bytes=($files|ForEach-Object {[long]$_.bytes}|Measure-Object -Sum).Sum;missing=$missing;files=$files;Git_mutated=$false};return}
if($missing.Count -or !$CpuDebugExitObserved0 -or (Test-Path -LiteralPath $aggregate) -or (Test-Path -LiteralPath $manifest)){throw 'Fresh complete r2 ten-gate evidence/root CPU exit0 required'}
$b=ReadJson $baseline;if($b.root_verified_checkpoint -ne $base){throw 'Wrong baseline'};VerifyTree $b.inputs;VerifyTree $b.canonical_GPU;VerifyTree @($b.source|Where-Object {[IO.Path]::GetFileName($_.path) -notin $five});foreach($s in $b.old_five_sources){VerifyTree $s.copy};VerifyTree $b.retained_observer_GPU_programs
$gpuIds=@{};$builds=@();foreach($c in 'Debug','Release'){$q=Join-Path $logs ($tag+$c+'_r2.build.json');$g=ReadJson $q;VerifyTree $g;if($g.status -ne 'full_authoritative_GPU_Rebuild_passed_no_helper_or_program_run' -or $g.configuration -ne $c -or !$g.canonical_GPU_unchanged -or $g.objects.Count -ne 110){throw 'Wrong r2 authoritative build'};CheckCall $g.project_call;$s=ReadJson $g.source_freeze.path;VerifyTree $s;if($s.source.Count -ne 5){throw 'Five current source hashes required'};$e=Entry $q;$gpuIds[$c]=$e.sha256;$builds+=$e}
$native=@();$components=@();foreach($q in $checks){$r=ReadJson $q;VerifyTree $r;if(!$r.passed -or $r.physical_acceptance){throw 'Required r2 gate failed'};CheckHelper $r.build;$d=ReadJson $r.completion.path;VerifyTree $d;if(!$d.passed -or $d.physical_acceptance){throw 'Completion rejected'}
  if($r.window){$n=if($r.window -eq 'Smoke'){3}else{17};if($r.samples -ne $n -or $r.native -ne 512 -or !$r.all_original15_exact -or !$r.all_actual_saved_time_step_signed_dterror_exact -or !$r.all_saved_observer_CSVs_exact -or !$r.final_live_native_csv_exact -or $r.private_feedback_tested){throw 'Native invariance gate differs'};foreach($c in $r.calls){CheckCall $c};foreach($e in $r.solvers){$v=ReadJson $e.path;VerifyTree $v;if(!$v.passed -or $v.native_frames -ne $n){throw 'Incomplete native solve'};CheckCall $v.call ($r.window -eq 'Smoke')};foreach($e in $r.adopted_controls){VerifyTree (ReadJson $e.path)};$native+=@{review=(Entry $q);samples=$r.samples;native=$r.native;metrics=$d}}
  else{CheckCall $r.call ($r.configuration -eq 'Debug');if($r.feedback_outer_loop_admitted){throw 'Full feedback Run held'};if($r.fixture -eq 'Feedback' -and ([bool]$d.optional_integration_executed -ne [bool]$r.integrated_component -or $d.physical_outer_loop_used -or $d.dynamic_Darcy_tested)){throw 'Prescribed component scope differs'};$components+=@{check=(Entry $q);fixture=$r.fixture;configuration=$r.configuration;integrated_component=$r.integrated_component;metrics=$d}}
}
$f=ReadJson (Join-Path $logs ($tag+'Feedback_Debug_r1_integrated_component.call.json'));VerifyTree $f;if($f.exit_code -ne 1 -or !$f.memcheck_zero_errors_and_leaks){throw 'Preserve exact failed r1 identity'}
$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$head=& git -C $repo rev-parse HEAD;$code=$LASTEXITCODE;$ErrorActionPreference=$old;if($code -or $head -ne $base){throw 'Changed Git base'}
$files=@(Paths|ForEach-Object {$e=Entry $_;if($e.bytes -gt 2097152 -or [IO.Path]::GetExtension($_) -notin '.h','.cpp','.cu','.ps1','.json','.csv','.out','.log','.xml'){throw "Unapproved/large text: $_"};$e})
WriteFresh $aggregate ([ordered]@{passed=$true;base=$base;builds=$builds;native=$native;components=$components;counts_from_actual_completions=$true;native_frame_instances=20;distinct_times=17;frame_pairs=40;native_ID_pairs=20480;static_suite_repeated_in_integrated_invocation=$true;cross_Debug_Release_byte_identity_claimed=$false;retained_r1_failure=(Entry (Join-Path $logs ($tag+'Feedback_Debug_r1_integrated_component.call.json')));CPU_Debug=@{log=(Entry $cpu);exit0_root_direct_observed=$true;sessionID=$null;inferred_from_log=$false};context=(Entry $context);physical_acceptance=$false;public_GPU_dynamic_accepted=$false})
$files+=Entry $aggregate;WriteFresh $manifest ([ordered]@{base=$base;ready_for_root_review=$true;aggregate=(Entry $aggregate);files=$files;count=$files.Count;bytes=($files|ForEach-Object {[long]$_.bytes}|Measure-Object -Sum).Sum;status_included=[bool]$IncludeValidationStatus;local_only='BI4/exe/obj/runtime/lib/PDB/binlog/VTK; duplicate author/source copies and per-frame empty logs/callJSON. Hash-bound locally, not raw cloud backup.';R1_drafts_excluded=$true;physical_acceptance=$false})
